-- Initial schema for a NEW database. Managed by Flyway; never run manually.
-- Derived from the application mappings using PostgreSQLDialect, then reviewed.
-- No accounts, campaigns or test data are inserted. Do not edit after release.

create table answers (
    id bigint generated by default as identity,
    correct boolean not null,
    text varchar(500) not null,
    question_id bigint not null,
    primary key (id)
);

create table badges (
    id bigint generated by default as identity,
    description varchar(1000),
    name varchar(255) not null unique,
    system_code varchar(255) unique check (system_code in ('FIRST_QUIZ','STUDENT','EXPERT')),
    primary key (id)
);

create table campaign_chapter_progress (
    id bigint generated by default as identity,
    completed boolean not null,
    completed_at timestamp(6),
    unlocked boolean not null,
    chapter_id bigint not null,
    user_id bigint not null,
    primary key (id),
    unique (user_id, chapter_id)
);

create table campaign_chapters (
    id bigint generated by default as identity,
    description varchar(1000),
    has_combat boolean not null,
    order_index integer not null,
    story_text varchar(8000) not null,
    title varchar(255) not null,
    campaign_id bigint not null,
    lesson_id bigint,
    quiz_id bigint,
    reward_badge_id bigint,
    primary key (id)
);

create table campaign_players (
    campaign_id bigint not null,
    user_id bigint not null
);

create table campaign_progress (
    id bigint generated by default as identity,
    completed boolean not null,
    completed_at timestamp(6),
    unlocked boolean not null,
    campaign_id bigint not null,
    user_id bigint not null,
    primary key (id),
    unique (user_id, campaign_id)
);

create table campaigns (
    id bigint generated by default as identity,
    description varchar(2000),
    difficulty varchar(255) not null check (difficulty in ('BEGINNER','INTERMEDIATE','ADVANCED')),
    name varchar(255) not null,
    master_id bigint,
    primary key (id)
);

create table characters (
    id bigint generated by default as identity,
    alive boolean not null,
    armor_class integer not null,
    attack_ability varchar(255) check (attack_ability in ('STRENGTH','DEXTERITY','INTELLIGENCE','WISDOM','CHARISMA')),
    character_class varchar(255),
    current_hp integer not null,
    damage_die integer not null,
    image_url varchar(255),
    level integer not null,
    max_hp integer not null,
    name varchar(255) not null,
    race varchar(255),
    spell_ability varchar(255) check (spell_ability in ('STRENGTH','DEXTERITY','INTELLIGENCE','WISDOM','CHARISMA')),
    spell_damage_die integer not null,
    spell_name varchar(255),
    spellcaster boolean not null,
    weapon_name varchar(255),
    campaign_id bigint,
    player_id bigint,
    source_template_id bigint,
    primary key (id),
    constraint uk_character_campaign_player unique (campaign_id, player_id),
    constraint ck_character_model_instance check ((player_id is null and source_template_id is null) or (player_id is not null and source_template_id is not null and source_template_id <> id))
);

create table character_stats (
    id bigint generated by default as identity,
    charisma integer not null,
    constitution integer not null,
    dexterity integer not null,
    intelligence integer not null,
    strength integer not null,
    wisdom integer not null,
    character_id bigint unique,
    primary key (id)
);

create table combat (
    id bigint generated by default as identity,
    completed boolean not null,
    completed_at timestamp(6),
    current_turn_index integer not null,
    outcome varchar(255) check (outcome in ('PLAYER_VICTORY','ENEMY_VICTORY')),
    campaign_id bigint not null,
    chapter_id bigint not null,
    encounter_id bigint not null,
    user_id bigint not null,
    primary key (id)
);

create table combat_events (
    combat_id bigint not null,
    action_type varchar(255) not null,
    attack_roll integer,
    attacker_id bigint,
    attacker_name varchar(255),
    critical boolean,
    damage integer,
    enemy boolean,
    healing integer not null,
    healing_die integer not null,
    healing_roll integer not null,
    hit boolean,
    target_armor_class integer,
    target_hp_before integer,
    target_id bigint,
    target_name varchar(255),
    target_remaining_hp integer,
    total_attack integer,
    event_index integer not null,
    primary key (combat_id, event_index)
);

create table combat_participants (
    id bigint generated by default as identity,
    alive boolean not null,
    current_hp integer not null,
    enemy boolean not null,
    healing_used integer not null,
    initiative integer not null,
    max_hp integer not null,
    character_id bigint,
    combat_id bigint not null,
    npc_id bigint,
    primary key (id)
);

create table combat_turn_order (
    combat_id bigint not null,
    turn_order bigint
);

create table encounter_npcs (
    id bigint generated by default as identity,
    quantity integer not null,
    encounter_id bigint not null,
    npc_id bigint not null,
    primary key (id)
);

create table encounters (
    id bigint generated by default as identity,
    description varchar(2000),
    title varchar(255) not null,
    chapter_id bigint not null unique,
    primary key (id)
);

create table lessons (
    id bigint generated by default as identity,
    content varchar(5000) not null,
    order_index integer not null,
    title varchar(255) not null,
    unlocked_by_default boolean not null,
    primary key (id)
);

create table npcs (
    id bigint generated by default as identity,
    armor_class integer not null,
    attack_modifier integer not null,
    damage_die integer not null,
    damage_modifier integer not null,
    description varchar(1000),
    dexterity integer not null,
    enemy boolean not null,
    healer boolean not null,
    healing_die integer not null,
    healing_modifier integer not null,
    healing_uses integer not null,
    image_url varchar(255),
    max_hp integer not null,
    name varchar(255) not null,
    owner_id bigint,
    primary key (id)
);

create table password_reset_tokens (
    id bigint generated by default as identity,
    expiration_date timestamp(6) not null,
    token varchar(255) not null unique,
    used boolean not null,
    user_id bigint not null unique,
    primary key (id)
);

create table questions (
    id bigint generated by default as identity,
    text varchar(1000) not null,
    quiz_id bigint not null,
    primary key (id)
);

create table quizzes (
    id bigint generated by default as identity,
    passing_score integer not null,
    title varchar(255) not null,
    lesson_id bigint not null unique,
    primary key (id)
);

create table user_badges (
    id bigint generated by default as identity,
    unlocked_at timestamp(6),
    badge_id bigint,
    user_id bigint,
    primary key (id),
    unique (user_id, badge_id)
);

create table user_lesson_progress (
    id bigint generated by default as identity,
    completed boolean not null,
    completed_at timestamp(6),
    unlocked boolean not null,
    lesson_id bigint,
    user_id bigint,
    primary key (id)
);

create table user_quiz_results (
    id bigint generated by default as identity,
    completed_at timestamp(6),
    correct_answers integer not null,
    passed boolean not null,
    score integer not null,
    total_questions integer not null,
    quiz_id bigint,
    user_id bigint,
    primary key (id)
);

create table users (
    id bigint generated by default as identity,
    avatar_url varchar(2048),
    email varchar(255) not null unique,
    learning_level varchar(255) check (learning_level in ('BEGINNER','INTERMEDIATE','ADVANCED')),
    password varchar(255) not null,
    role varchar(255) check (role in ('PLAYER','MASTER')),
    token_version bigint not null,
    username varchar(255) not null unique,
    primary key (id)
);

